"""Transitions generated by MotionBricks between OUR clips' poses (trial).

Runs in MotionBricks' own environment, from its folder (its TensorRT plan cache is there):

  cd C:/Dev/motionbricks
  uv run python <repo>/tools/motionbricks/mb_generate.py --dump-skeleton <soma_skeleton.npz>
  uv run python <repo>/tools/motionbricks/mb_generate.py --clips <dir of our clips as SOMA BVH> --jobs <jobs.json> --out <out.npz>

A job (jobs.json, a list): {"name", "context": [clip, time the four context poses end at],
"target": [clip, time of the first target pose], "forward": m, "left": m, "turn": degrees (where the target stands
against the last context pose), "poses": 1..4 target poses, "before": s of clip A shown first, "after": s of clip B
shown after}. Out: per job the whole sequence at 30 Hz as local transforms [frames, joints, 7] (position xyz, quaternion
xyzw; the first joint, Hips, in the runtime's world: Z up, facing +X), the generated part's first and last frame, its
foot contacts and how long the generation took.
"""
import argparse
import json
import time
from pathlib import Path

import numpy as np
import warp as wp

from motionbricks.io.bvh import load_bvh
from motionbricks.io.usd import load_skeleton_from_usd
from motionbricks.io.utils import SOMA_SKELETON_PRIM_PATH, get_asset_file
from motionbricks.model.config import MotionBricksInferenceConfig
from motionbricks.model.contract import MODEL_POSES_PER_TOKEN, MODEL_SAMPLE_RATE
from motionbricks.model.soma.contract import SOMA_N1_FP32_ONNX_PATH
from motionbricks.model.soma.engine import MotionBricksSOMAEngine
from motionbricks.utils.space_conversion_utils import FacingDirectionType, SpaceConverter


def qmul(a, b):
    ax, ay, az, aw = np.moveaxis(a, -1, 0)
    bx, by, bz, bw = np.moveaxis(b, -1, 0)
    return np.stack([aw * bx + ax * bw + ay * bz - az * by,
                     aw * by - ax * bz + ay * bw + az * bx,
                     aw * bz + ax * by - ay * bx + az * bw,
                     aw * bw - ax * bx - ay * by - az * bz], -1)


def qrot(q, v):
    u, w = q[..., :3], q[..., 3:]
    t = 2.0 * np.cross(u, v)
    return v + w * t + np.cross(u, t)


def zquat(angle):
    return np.array([0.0, 0.0, np.sin(angle / 2.0), np.cos(angle / 2.0)])


def heading(pose, left_leg, right_leg):
    """the root's ground place and facing angle (Z up, X forward, Y left) from the hips and the two thighs"""
    root_p, root_q = pose[0, :3], pose[0, 3:]
    left = qrot(root_q, pose[left_leg, :3]) - qrot(root_q, pose[right_leg, :3])
    return root_p[:2].copy(), float(np.arctan2(-left[0], left[1]))


def place(poses, at, angle_now, angle_want):
    """move the roots of poses [N, J, 7] so the first stands at `at` (x, y) facing angle_want"""
    out = poses.copy()
    turn = zquat(angle_want - angle_now)
    p0 = poses[0, 0, :3].copy()
    for i in range(len(out)):
        d = out[i, 0, :3] - p0
        d[2] = 0.0
        rd = qrot(turn, d)
        out[i, 0, 0] = at[0] + rd[0]
        out[i, 0, 1] = at[1] + rd[1]
        out[i, 0, 3:] = qmul(turn, out[i, 0, 3:])
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dump-skeleton")
    ap.add_argument("--clips")
    ap.add_argument("--jobs")
    ap.add_argument("--out")
    ap.add_argument("--fp16", action="store_true")
    a = ap.parse_args()
    wp.init()
    wp.set_device("cuda:0")
    skeleton = load_skeleton_from_usd(get_asset_file("human", "soma_base_skel_minimal_no_root.usd"), SOMA_SKELETON_PRIM_PATH)
    names = list(skeleton.joint_names)
    parents = np.array([skeleton.joint_parent(i) for i in range(len(names))])
    if a.dump_skeleton:
        np.savez(a.dump_skeleton, names=np.array(names), parents=parents, reference=skeleton.reference_local_transforms.numpy())
        print("skeleton:", len(names), "joints")
        if not a.jobs:
            return
    to_runtime = SpaceConverter(FacingDirectionType.MUJOCO).convert_transform(wp.transform_identity())
    clips = {p.stem: load_bvh(str(p), skeleton) for p in sorted(Path(a.clips).glob("*.bvh"))}
    print("clips:", ", ".join(f"{k} {v.duration:.2f} s" if hasattr(v, "duration") else k for k, v in clips.items()))
    jobs = json.load(open(a.jobs, encoding="utf-8"))
    li, ri = names.index("LeftLeg"), names.index("RightLeg")
    path = SOMA_N1_FP32_ONNX_PATH
    if a.fp16:
        from motionbricks.model.soma.contract import SOMA_N1_FP16_ONNX_PATH
        path = SOMA_N1_FP16_ONNX_PATH
    engine = MotionBricksSOMAEngine(path, model_to_runtime=to_runtime)
    results = {}
    with engine, wp.ScopedStream(engine.stream):
        context = engine.create_input(skeleton)
        target = engine.create_input(skeleton)
        output = engine.create_output(skeleton)
        buf = wp.empty_like(context.poses)

        def sample(clip, t0, n, rate=MODEL_SAMPLE_RATE):
            frames = []
            for k in range(n):
                clip.sample(t0 + k / rate, buf[0], root_offset=to_runtime, stream=engine.stream)
                engine.synchronize()
                frames.append(buf[0].numpy().copy())
            return np.array(frames)

        for job in jobs:
            ca, ct = job["context"]
            ta, tt = job["target"]
            ctx = sample(clips[ca], ct - (MODEL_POSES_PER_TOKEN - 1) / MODEL_SAMPLE_RATE, MODEL_POSES_PER_TOKEN)
            npose = int(job.get("poses", 4))
            tgt = sample(clips[ta], tt, npose)
            at, ang = heading(ctx[-1], li, ri)
            fwd = np.array([np.cos(ang), np.sin(ang)])
            lef = np.array([-np.sin(ang), np.cos(ang)])
            want = at + fwd * job.get("forward", 0.0) + lef * job.get("left", 0.0)
            _, tang = heading(tgt[0], li, ri)
            tgt = place(tgt, want, tang, ang + np.radians(job.get("turn", 0.0)))
            context.update_from_poses(wp.array(ctx, dtype=wp.transform), stream=engine.stream)
            target.update_from_poses(wp.array(tgt, dtype=wp.transform), stream=engine.stream)
            cfg = MotionBricksInferenceConfig(allowed_token_counts=tuple(job.get("tokens", range(8, 15))))
            t0 = time.perf_counter()
            engine.generate_animation(context, target, output, config=cfg)
            engine.synchronize()
            took = time.perf_counter() - t0
            n = output.num_frames
            gen = output.poses[:n].numpy().copy()
            contacts = output.foot_contacts[:n].numpy().copy()
            # what was shown before (clip A up to the context) and after (clip B on from the target, where it was put)
            before = sample(clips[ca], ct - job.get("before", 1.0), int(round(job.get("before", 1.0) * MODEL_SAMPLE_RATE)))
            after = sample(clips[ta], tt, int(round(job.get("after", 1.0) * MODEL_SAMPLE_RATE)) + 1)
            after = place(after, want, tang, ang + np.radians(job.get("turn", 0.0)))[1:]
            seq = np.concatenate([before, gen, after])
            results[job["name"]] = dict(seq=seq, gen=np.array([len(before), len(before) + n - 1]), contacts=contacts,
                                        took=np.array(took))
            print(f"{job['name']}: {n} frames generated ({n / MODEL_SAMPLE_RATE:.2f} s) in {took * 1000:.1f} ms; "
                  f"target {np.round(want, 2)} facing {np.degrees(ang) + job.get('turn', 0.0):.0f}")
    flat = {"names": np.array(names), "parents": parents, "jobs": np.array(list(results))}
    for k, v in results.items():
        for kk, vv in v.items():
            flat[f"{k}__{kk}"] = vv
    np.savez(a.out, **flat)


if __name__ == "__main__":
    main()
